(() => {
 const $=s=>document.querySelector(s),money=n=>'₹'+Math.round(n).toLocaleString('en-IN'),num=n=>Number(n.toFixed(1)).toLocaleString('en-IN');
 function values(form){const result={};for(const el of form.elements){if(el.name)result[el.name]=el.type==='checkbox'?el.checked:Number(el.value);}return result;}
 function row(label,value){return '<div><dt>'+label+'</dt><dd>'+value+'</dd></div>';}
 const solar=$('#solar-form');
 if(solar){const result=$('#solar-result');const presets=[1,2,3,5];
  function calc(){if(!solar.checkValidity()){result.textContent='Please enter valid values within the shown limits.';return;}const v=values(solar),r=RenewCalc.solar(v);result.innerHTML='<span class="eyebrow">ESTIMATED ANNUAL NET SAVING</span><div class="result-num">'+money(r.netSaving)+'</div><dl class="cost-breakdown">'+row('Electricity generated',num(r.generation/365)+' units/day · '+num(r.generation)+' units/year')+row('Used directly / grid purchases avoided',num(r.direct/12)+' units/month')+row('Surplus exported',num(r.exported/12)+' units/month')+row('Monthly saving before maintenance',money(r.grossSaving/12))+row('Installation before support',money(v.cost))+row('Potential central support',v.eligible?money(r.subsidy)+' (conditional)':'Not applied')+row('Cost after selected support',money(r.netCost))+row('Simple payback',r.payback===null?'Not reached with these inputs':num(r.payback)+' years')+'</dl><p class="micro">A starting size to discuss with an installer: '+num(r.recommended)+' kW, based only on your roof and annual usage. A site survey and approved connection capacity decide the actual size.</p>'+(v.roof<r.roofNeeded?'<p class="calc-warning">Your chosen '+v.kw+' kW needs about '+num(r.roofNeeded)+' sq ft under this planning rule. The entered roof is too small; these figures do not establish a feasible installation.</p>':'')+'<details><summary>How this estimate is worked out</summary><p>Annual generation = kW × full-sun hours × performance factor × 365. Direct use is capped by both your chosen daytime-use share and total household consumption. Only direct use avoids retail-priced purchases; surplus uses the separate export rate.</p><p>Net annual saving = direct-use value + export credit − maintenance. Payback = cost after selected support ÷ net annual saving. Excludes financing, fixed electricity charges, degradation, inverter replacement and battery costs. Annual averages hide seasonal and hourly differences.</p></details>';}
  solar.addEventListener('input',()=>{document.querySelectorAll('[data-house]').forEach(b=>b.setAttribute('aria-pressed','false'));calc();});solar.addEventListener('submit',e=>e.preventDefault());document.querySelectorAll('[data-house]').forEach(b=>b.addEventListener('click',()=>{const kw=presets[+b.dataset.house];const v={roof:kw*100,kw,units:kw*120,tariff:8,cost:kw*65000,sun:5,performance:80,self:50,exportRate:0,maintenance:kw*650};for(const [key,val]of Object.entries(v))solar.elements.namedItem(key).value=val;document.querySelectorAll('[data-house]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));calc();}));calc();
 }
 const ev=$('#ev-running-form');if(ev){function calc(){const r=$('#ev-running-result');if(!ev.checkValidity()){r.textContent='Please enter valid values within the shown limits.';return;}const x=RenewCalc.ev(values(ev));r.innerHTML='<span class="eyebrow">ESTIMATED YEARLY '+(x.annual<0?'EXTRA ENERGY COST':'ENERGY SAVING')+'</span><div class="result-num">'+money(Math.abs(x.annual))+'</div><dl class="cost-breakdown">'+row('Petrol / month',money(x.petrol))+row('Charging / month',money(x.electricity))+'</dl><details><summary>See the calculation</summary><p>Petrol = distance ÷ mileage × petrol price. Charging = distance × kWh per 100 km ÷ 100 × (1 + charging loss %) × tariff. Annual difference = 12 × the monthly difference.</p></details>';}
 ev.addEventListener('input',calc);ev.addEventListener('submit',e=>e.preventDefault());$('#ev-running-type').addEventListener('change',e=>{const p={car:[1000,15,15],scooter:[600,45,3],auto:[3000,25,7]}[e.target.value];['km','eff','cons'].forEach((n,i)=>ev.elements.namedItem(n).value=p[i]);calc();});calc();}
 document.querySelectorAll('.road-form').forEach(form=>{const out=form.querySelector('.road-result'),el=n=>form.elements.namedItem(n);let city;try{city=localStorage.getItem('renew-city');}catch{}if(city&&window.roadRules[city])el('city').value=city;
 function calc(event){if(event&&['price','variant','city','type'].includes(event.target.name)){el('override').value='';if(event.target.name==='variant'&&el('variant').value)el('price').value=el('variant').value;}
 if(!form.checkValidity()){out.textContent='Enter a positive vehicle price and valid, non-negative costs.';return;}
 const city=el('city').value,rule=window.roadRules[city];if(!rule){out.textContent='Select a listed Indian city.';return;}try{localStorage.setItem('renew-city',city);}catch{}
 const v={price:+el('price').value,insurance:+el('insurance').value,type:el('type').value,override:el('override').value===''?null:+el('override').value},r=RenewCalc.road(v,rule);
 const incomplete=r.incomplete||city==='bengaluru';out.innerHTML='<span class="eyebrow">'+(incomplete?'ESTIMATED SUBTOTAL · COSTS STILL TO CONFIRM':'ESTIMATED ON-ROAD AMOUNT')+'</span><strong class="road-total">'+money(r.subtotal)+'</strong><dl class="cost-breakdown">'+row('Ex-showroom price',money(v.price))+row('Road tax including modelled cess',r.tax===null?'Unconfirmed — not included':money(r.tax)+(v.override!==null?' · your quote':' · estimate'))+row('RC issuance / new registration mark fee','₹0 · battery-EV exemption')+row('Insurance',v.insurance===0?'Unconfirmed — not included':money(v.insurance)+' · your quote')+row('TCS on sale above ₹10 lakh',money(r.tcs))+'</dl><p class="micro">'+r.note+'</p>'+(r.tax===null?'<p class="calc-warning">This is not a complete on-road total: road tax is still missing. Use a confirmed RTO/dealer amount in the override if available.</p>':'')+'<p class="micro">'+(v.type==='three-wheeler'?'Commercial fitness, registration classification and other applicable statutory charges require confirmation. ':'')+'HSRP/plate, smart-card or state welfare charges may be extra; no blanket amount is invented. Optional accessories and dealer fees are excluded. TCS is estimated at 1% of the entered sale price above ₹10 lakh for a normal PAN-backed purchase; seller exceptions and final tax treatment need confirmation. It may be claimable as income-tax credit.</p><details><summary>Rules and sources</summary><a target="_self" href="'+rule.source+'">State rule / transport department ↗</a><br><a target="_self" href="https://www.pib.gov.in/PressReleasePage.aspx?PRID=1741959">Central battery-EV registration-fee exemption ↗</a><br><a target="_self" href="https://www.incometaxindia.gov.in/w/tax-collection-at-source-tcs-)">TCS guidance ↗</a></details>';
 const badge=document.querySelector('.location-benefit');if(badge)badge.textContent=el('city').selectedOptions[0].text+': '+(r.tax===null?'road-tax position needs verification.':r.tax===0?'road-tax exemption modelled; this is separate from purchase-subsidy eligibility.':'estimated road tax '+money(r.tax)+'. Purchase-subsidy rules are separate.');}
 form.addEventListener('input',calc);form.addEventListener('change',calc);form.addEventListener('submit',e=>e.preventDefault());calc();
 });
})();
